CREATE TABLE meta (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO meta VALUES ('revision',0),('policyRevision',0);
CREATE TABLE roots (id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE scan_runs (id TEXT PRIMARY KEY, root_id TEXT NOT NULL REFERENCES roots(id), folder TEXT NOT NULL, verify INTEGER NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, error TEXT, seen INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_scan_per_root ON scan_runs(root_id) WHERE state IN ('queued','running');
CREATE TABLE contents (id TEXT PRIMARY KEY CHECK(length(id)=64), size INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE file_instances (id INTEGER PRIMARY KEY, root_id TEXT NOT NULL REFERENCES roots(id), path TEXT NOT NULL, size INTEGER, mtime_ns INTEGER, content_id TEXT REFERENCES contents(id), state TEXT NOT NULL, error TEXT, last_scan TEXT REFERENCES scan_runs(id), UNIQUE(root_id,path));
CREATE INDEX files_content ON file_instances(content_id);
CREATE INDEX files_scope ON file_instances(root_id,state,path);
CREATE TABLE file_versions (id INTEGER PRIMARY KEY, instance_id INTEGER NOT NULL REFERENCES file_instances(id), content_id TEXT REFERENCES contents(id), size INTEGER, mtime_ns INTEGER, state TEXT NOT NULL, scan_id TEXT NOT NULL REFERENCES scan_runs(id), at TEXT NOT NULL);
CREATE TABLE photos (content_id TEXT PRIMARY KEY REFERENCES contents(id), filename TEXT NOT NULL, format TEXT NOT NULL, folder TEXT NOT NULL, capture_date TEXT, capture_source TEXT NOT NULL DEFAULT 'unknown', width INTEGER NOT NULL DEFAULT 0, height INTEGER NOT NULL DEFAULT 0, origin TEXT NOT NULL DEFAULT 'unknown', band TEXT NOT NULL DEFAULT 'low', triage TEXT NOT NULL DEFAULT 'awaiting_analysis', sensitive TEXT NOT NULL DEFAULT 'unknown', importance TEXT NOT NULL DEFAULT 'unknown', faces TEXT NOT NULL DEFAULT '"not_checked"', evidence TEXT NOT NULL DEFAULT '[]', protection TEXT NOT NULL DEFAULT '[]', document_type TEXT, duplicate_set TEXT, camera TEXT, gps TEXT, review_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE group_assignments (content_id TEXT PRIMARY KEY REFERENCES contents(id), ai_group TEXT NOT NULL DEFAULT 'unclassified', manual_group TEXT);
CREATE TABLE decisions (content_id TEXT PRIMARY KEY REFERENCES contents(id), decision TEXT NOT NULL DEFAULT 'undecided' CHECK(decision IN ('undecided','keep','clutter','later')), version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE cached_media (id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES contents(id), fingerprint TEXT NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, UNIQUE(content_id,fingerprint,kind));
CREATE TABLE stage_jobs (id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES contents(id), stage TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', owner TEXT, token TEXT, expires REAL, attempt INTEGER NOT NULL DEFAULT 0, error TEXT, UNIQUE(content_id,stage,fingerprint));
CREATE INDEX stage_queue ON stage_jobs(state,stage,expires);
CREATE TABLE stage_results (content_id TEXT NOT NULL REFERENCES contents(id), stage TEXT NOT NULL, fingerprint TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES stage_jobs(id), token TEXT NOT NULL, payload TEXT NOT NULL, ack TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(content_id,stage,fingerprint));
CREATE TABLE embedding_indexes (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, config TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL);
CREATE UNIQUE INDEX one_primary_index ON embedding_indexes(role) WHERE role='primary';
CREATE TABLE embeddings (content_id TEXT NOT NULL REFERENCES contents(id), index_id TEXT NOT NULL REFERENCES embedding_indexes(id), vector BLOB NOT NULL, PRIMARY KEY(content_id,index_id));
CREATE TABLE actions (id TEXT PRIMARY KEY, label TEXT NOT NULL, scope TEXT NOT NULL, created_at TEXT NOT NULL, undo_of TEXT UNIQUE REFERENCES actions(id));
CREATE TABLE audit_log (id INTEGER PRIMARY KEY, action_id TEXT NOT NULL REFERENCES actions(id), content_id TEXT REFERENCES contents(id), kind TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, applied_version INTEGER, at TEXT NOT NULL);
CREATE INDEX audit_actions ON audit_log(action_id);
CREATE TABLE selections (id TEXT PRIMARY KEY, query TEXT NOT NULL, fingerprint TEXT NOT NULL, revision INTEGER NOT NULL, policy_revision INTEGER NOT NULL, include_protected INTEGER NOT NULL, excluded INTEGER NOT NULL, protected_count INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE selection_items (selection_id TEXT NOT NULL REFERENCES selections(id), content_id TEXT NOT NULL REFERENCES contents(id), version INTEGER NOT NULL, PRIMARY KEY(selection_id,content_id));
CREATE TABLE bulk_jobs (id TEXT PRIMARY KEY, selection_id TEXT NOT NULL UNIQUE REFERENCES selections(id), decision TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', action_id TEXT NOT NULL REFERENCES actions(id), created_at TEXT NOT NULL);
CREATE TABLE bulk_items (job_id TEXT NOT NULL REFERENCES bulk_jobs(id), content_id TEXT NOT NULL REFERENCES contents(id), expected_version INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', reason TEXT, PRIMARY KEY(job_id,content_id));
CREATE TABLE events (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'suggested', place TEXT, parent_trip_id TEXT, version INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE event_members (content_id TEXT PRIMARY KEY REFERENCES contents(id), event_id TEXT NOT NULL REFERENCES events(id));
CREATE INDEX event_members_event ON event_members(event_id);
CREATE TABLE event_edits (id INTEGER PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), action_id TEXT NOT NULL REFERENCES actions(id), before_json TEXT NOT NULL, after_json TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE settings (section TEXT PRIMARY KEY, value TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0);
INSERT INTO settings VALUES ('protection','{"protectedFolders":[],"ageBefore":null}',0),('appearance','{"theme":"dark","density":"compact","thumbnailSize":"medium","autoAdvance":false}',0),('models','{"primaryIndex":null,"d3Endpoint":"/v1/systemone","d3Schema":null}',0),('setup','{"complete":false}',0);
CREATE TABLE export_plans (id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, inputs TEXT NOT NULL, totals TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'preview');
CREATE TABLE export_entries (plan_id TEXT NOT NULL REFERENCES export_plans(id), content_id TEXT NOT NULL REFERENCES contents(id), instance_id INTEGER NOT NULL REFERENCES file_instances(id), source TEXT NOT NULL, destination TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY(plan_id,content_id), UNIQUE(plan_id,destination));
CREATE TABLE export_runs (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL UNIQUE REFERENCES export_plans(id), state TEXT NOT NULL, created_at TEXT NOT NULL, error TEXT);
CREATE TABLE export_operations (id INTEGER PRIMARY KEY, run_id TEXT NOT NULL REFERENCES export_runs(id), content_id TEXT NOT NULL REFERENCES contents(id), destination TEXT NOT NULL, state TEXT NOT NULL, output_hash TEXT, output_identity TEXT, error TEXT, UNIQUE(run_id,content_id));
